// This file is generated by AI.

// 文件变更批次解析的断言 (issue #25 的第三处症状: 事件风暴把语言服务与主线程一起拖死)。
//
// 钉住三件事:
//
// 1. 复核用的存在性查询**有并发上限** —— 一次性拍出成千上万个 IPC 正是卡死的来源;
// 2. 结果顺序与输入一致 (语言服务按顺序处理, 顺序错乱会让"创建后删除"变成"删除后创建");
// 3. 爆发超过阈值时不做复核, 也不因此丢掉任何一条变更。

import { describe, expect, it, vi } from 'vitest';

import {
  DEFAULT_MAX_STAT_PATHS,
  mapLimited,
  resolveChanges,
  type ExistsResult,
  type FileChangeType,
} from '../src/lsp/change-batch';

/** 造一个"只有列出的路径存在"的查询替身, 并记录并发峰值 */
function createExists(existing: Record<string, ExistsResult>) {
  let inFlight = 0;
  let peak = 0;
  const asked: string[] = [];
  const exists = async (path: string): Promise<ExistsResult> => {
    asked.push(path);
    inFlight += 1;
    peak = Math.max(peak, inFlight);
    await new Promise((resolve) => setTimeout(resolve, 0));
    inFlight -= 1;
    return existing[path] ?? { exists: false, isDirectory: false };
  };
  return {
    exists,
    asked,
    get peak() {
      return peak;
    },
  };
}

describe('mapLimited', () => {
  it('保持结果顺序', async () => {
    const result = await mapLimited([3, 1, 2], 2, async (value) => {
      await new Promise((resolve) => setTimeout(resolve, value));
      return value * 10;
    });

    expect(result).toEqual([30, 10, 20]);
  });

  it('并发不超过上限', async () => {
    const probe = createExists({});
    const items = Array.from({ length: 40 }, (_, index) => `p${index}`);

    await mapLimited(items, 4, probe.exists);

    expect(probe.peak).toBeLessThanOrEqual(4);
  });

  it('空列表直接返回', async () => {
    const run = vi.fn();
    expect(await mapLimited([], 4, run)).toEqual([]);
    expect(run).not.toHaveBeenCalled();
  });
});

describe('resolveChanges', () => {
  it('删除事件本身就是结论, 不再查询', async () => {
    const exists = vi.fn();
    const changes = await resolveChanges([['a.txt', 3]] as [string, FileChangeType][], { exists });

    expect(changes).toEqual([{ path: 'a.txt', type: 3 }]);
    expect(exists).not.toHaveBeenCalled();
  });

  it('修改事件按当前磁盘状态复核: 已消失的路径读作删除 (重命名)', async () => {
    const probe = createExists({ 'still-here.txt': { exists: true, isDirectory: false } });

    const changes = await resolveChanges(
      [
        ['renamed-away.txt', 2],
        ['still-here.txt', 2],
      ] as [string, FileChangeType][],
      { exists: probe.exists }
    );

    expect(changes).toEqual([
      { path: 'renamed-away.txt', type: 3 },
      { path: 'still-here.txt', type: 2 },
    ]);
  });

  it('目录事件不转发', async () => {
    const probe = createExists({ 'figure/model': { exists: true, isDirectory: true } });

    const changes = await resolveChanges([['figure/model', 2]] as [string, FileChangeType][], {
      exists: probe.exists,
    });

    expect(changes).toEqual([]);
  });

  it('创建事件原样转发', async () => {
    const probe = createExists({ 'scene/start.txt': { exists: true, isDirectory: false } });

    const changes = await resolveChanges([['scene/start.txt', 1]] as [string, FileChangeType][], {
      exists: probe.exists,
    });

    expect(changes).toEqual([{ path: 'scene/start.txt', type: 1 }]);
  });

  it('爆发超过阈值时不再逐条复核, 但一条变更都不丢', async () => {
    const probe = createExists({});
    const batch: [string, FileChangeType][] = Array.from({ length: DEFAULT_MAX_STAT_PATHS + 1 }, (_, index) => [
      `figure/p${index}.json`,
      2,
    ]);

    const changes = await resolveChanges(batch, { exists: probe.exists });

    expect(probe.asked).toHaveLength(0);
    expect(changes).toHaveLength(batch.length);
    expect(changes[0]).toEqual({ path: 'figure/p0.json', type: 2 });
  });

  it('复核结果与输入顺序一一对应', async () => {
    const probe = createExists({ 'b.txt': { exists: true, isDirectory: false } });

    const changes = await resolveChanges(
      [
        ['a.txt', 2],
        ['b.txt', 1],
        ['c.txt', 3],
        ['d.txt', 1],
      ] as [string, FileChangeType][],
      { exists: probe.exists, concurrency: 2 }
    );

    expect(changes).toEqual([
      { path: 'a.txt', type: 3 },
      { path: 'b.txt', type: 1 },
      { path: 'c.txt', type: 3 },
      { path: 'd.txt', type: 3 },
    ]);
  });
});
